import {AdvertisingPlatform,AD_PLACEMENTS} from './advertising-platform.mjs';
import {shopOffers,shopToday,GOLD_SHOP_OFFERS} from './shop-state.mjs';
import {commitShopPurchase} from './shop-purchases.mjs';
import {commitShopReward} from './shop-rewards.mjs';
import {loadSolo} from './campaign-profile.mjs';
import {itemInfo} from './campaign-growth-data.mjs';
import {sheetStyle} from './campaign-system-ui.mjs';
import {installOnboarding} from './onboarding-guide.mjs';
import './platform.mjs';
const ads=new AdvertisingPlatform(globalThis.arcaneMobile?.ads||globalThis.arcaneAds||null),root=document.getElementById('shop-rewards'),status=document.getElementById('shop-status');let available=false,busy=false,testMode=false,tab='ads',purchase=null;
const tabs=document.createElement('nav');tabs.className='shop-tabs';tabs.setAttribute('aria-label','商店类别');tabs.innerHTML='<button data-shop-tab="ads" aria-pressed="true">秘境馈赠</button><button data-shop-tab="gold" aria-pressed="false">金币商店</button>';document.querySelector('.shop-intro').replaceChildren(tabs);
const confirm=document.createElement('dialog');confirm.className='shop-confirm';confirm.innerHTML='<form method="dialog"><small>THE WAYFARER’S OFFER</small><h2>确认购买</h2><i class="shop-item"></i><h3></h3><p></p><div><button value="cancel">返回商店</button><button type="button" data-confirm-buy>确认购买</button></div></form>';document.body.append(confirm);
function iconStyle(type){const i=itemInfo({type});return sheetStyle(i.sheet||'items',i.icon);}
function openPurchase(id){const o=GOLD_SHOP_OFFERS.find(o=>o.id===id);if(!o)return;purchase=o;confirm.querySelector('i').style.cssText=iconStyle(o.type);confirm.querySelector('h3').textContent=itemInfo({type:o.type}).name+' ×1';confirm.querySelector('p').textContent='花费 '+o.price+' 金币';confirm.showModal();}
confirm.addEventListener('close',()=>{purchase=null;});
confirm.querySelector('[data-confirm-buy]').addEventListener('click',async()=>{if(!purchase||busy)return;const id=purchase.id;busy=true;confirm.querySelector('[data-confirm-buy]').disabled=true;try{const buy=()=>commitShopPurchase(localStorage,id),result=await (navigator.locks?.request?navigator.locks.request('arcane-shop-purchase',buy):buy());status.textContent='已购买 '+itemInfo({type:result.offer.type}).name+' ×1，已放入背包。';confirm.close();}catch(e){status.textContent=e.message;confirm.querySelector('p').textContent=e.message;}finally{busy=false;confirm.querySelector('[data-confirm-buy]').disabled=false;render();}});
tabs.addEventListener('click',e=>{const b=e.target.closest('[data-shop-tab]');if(!b||busy)return;tab=b.dataset.shopTab;status.textContent=tab==='gold'?'选择物品，使用金币购买。':'自愿观看广告领取馈赠；取消或失败不扣次数。';render();});
function offerButton(o,today){if((today.counts[o.id]||0)>=o.limit)return '今日已领完';if(!available)return '广告补给 · 暂未开放';if(o.adsRequired===2)return today.ticketAds?'再看1次 · 领取抽奖券':'观看第1次广告';return '观看广告 · 领取';}
function render(){const profile=loadSolo(localStorage),today=shopToday(profile);document.getElementById('shop-coins').textContent=profile.coins;root.dataset.catalog=tab;root.setAttribute('aria-label',tab==='gold'?'金币商店':'广告补给');tabs.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.shopTab===tab)));document.querySelector('.shop-shell footer label').hidden=tab==='gold';if(tab==='gold'){root.innerHTML=GOLD_SHOP_OFFERS.map(o=>`<article class="shop-offer"><i class="shop-item" aria-hidden="true" style="${iconStyle(o.type)}"></i><h3>${itemInfo({type:o.type}).name}</h3><p>${o.copy}</p><small>持有 ${profile.bag.filter(i=>i.type===o.type).reduce((n,i)=>n+i.count,0)}</small><button data-buy="${o.id}" ${busy?'disabled':''}>购买 · ${o.price}金币</button></article>`).join('');return;}root.innerHTML=shopOffers(profile).map(o=>`<article class="shop-offer"><i class="shop-item" aria-hidden="true" style="${iconStyle(o.icon)}"></i><h3>${o.name}</h3><p>${o.copy}</p><small>今日 ${today.counts[o.id]||0} / ${o.limit}${o.adsRequired===2?' · 广告进度 '+(today.ticketAds||0)+' / 2':''}</small><button data-offer="${o.id}" ${busy||(today.counts[o.id]||0)>=o.limit?'disabled':''}>${offerButton(o,today)}</button></article>`).join('');}
root.addEventListener('click',e=>{const b=e.target.closest('[data-buy]');if(b&&!busy)openPurchase(b.dataset.buy);});
root.addEventListener('click',async e=>{const b=e.target.closest('[data-offer]');if(!b||busy)return;if(!available){status.textContent='广告补给暂未开放，正常探索与通关奖励照常获得。';return;}if(!document.getElementById('shop-privacy').checked){status.textContent='请先阅读并确认隐私与广告说明。';return;}busy=true;render();try{const result=await ads.showRewarded(b.dataset.offer==='ticket'?AD_PLACEMENTS.ticket:b.dataset.offer==='coins'?AD_PLACEMENTS.coins:AD_PLACEMENTS.item,{privacyAccepted:true});if(!result.completed){const failed=['loadFailed','loadTimeout','showFailed','showTimeout','videoFailed','notAvailable'].includes(result.reason);status.textContent=failed?`广告暂时加载失败${Number.isInteger(result.errorCode)?'（'+result.errorCode+'）':''}，请稍后再试，未扣领取次数。`:'本次未完成广告，奖励和领取次数均未改变。';return;}const next=commitShopReward(localStorage,b.dataset.offer,result);status.textContent=b.dataset.offer==='ticket'?(next.shop.ticketAds?'已保存第1次广告进度，再看1次即可获得1张抽奖券。':'获得1张抽奖券，已直接到账；每日任务同步计为领取。'):'馈赠已保存：金币已到账，道具可在背包查看，每日任务同步计为领取。';}catch(error){status.textContent=error.message;}finally{busy=false;render();}});
render();ads.status().then(s=>{available=s.configured&&s.rewarded;testMode=s.testMode===true;status.textContent=available?(testMode?'广告联调测试中：自愿观看测试广告验证奖励，尚未开放正式变现。':'选择需要的补给，自愿观看后领取。'):'广告补给暂未开放，正常探索与通关奖励照常获得。';render();}).catch(()=>{status.textContent='暂时没有可观看的广告，请稍后再来。';});
installOnboarding('shop');
